-- M6 Teenused (docs/13-teenused.md). Generated by drizzle-kit in two passes (drop, then create) so
-- the old M0 placeholder tables are replaced without interactive rename prompts, merged into one file.
-- `services` and `bookings` had no API, seed or writer before M6, so they are dropped instead of
-- converted. `service_providers` is kept; its new NOT NULL columns fail loudly if anyone inserted
-- rows by hand, which is safer than inventing an area or a location for them.

-- btree_gist lets a GiST index combine "=" on provider_id with "&&" on a time range (see the end).
CREATE EXTENSION IF NOT EXISTS btree_gist;--> statement-breakpoint
DROP TABLE "bookings" CASCADE;--> statement-breakpoint
DROP TABLE "services" CASCADE;--> statement-breakpoint
DROP TYPE "public"."booking_status";--> statement-breakpoint
CREATE TYPE "public"."booking_status" AS ENUM('confirmed', 'cancelled', 'completed');--> statement-breakpoint
CREATE TABLE "booking_dogs" (
	"booking_id" uuid NOT NULL,
	"dog_id" uuid NOT NULL,
	CONSTRAINT "booking_dogs_booking_id_dog_id_pk" PRIMARY KEY("booking_id","dog_id")
);
--> statement-breakpoint
CREATE TABLE "bookings" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" text NOT NULL,
	"provider_id" uuid NOT NULL,
	"service_id" uuid NOT NULL,
	"starts_at" timestamp with time zone NOT NULL,
	"ends_at" timestamp with time zone NOT NULL,
	"note" text,
	"price_cents" integer NOT NULL,
	"price_is_from" boolean NOT NULL,
	"status" "booking_status" DEFAULT 'confirmed' NOT NULL,
	"cancelled_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "bookings_time_order" CHECK ("bookings"."ends_at" > "bookings"."starts_at"),
	CONSTRAINT "bookings_note_length" CHECK ("bookings"."note" is null or char_length("bookings"."note") <= 300),
	CONSTRAINT "bookings_cancelled_at" CHECK (("bookings"."status" = 'cancelled') = ("bookings"."cancelled_at" is not null))
);
--> statement-breakpoint
CREATE TABLE "provider_hours" (
	"provider_id" uuid NOT NULL,
	"weekday" integer NOT NULL,
	"opens_at" time NOT NULL,
	"closes_at" time NOT NULL,
	CONSTRAINT "provider_hours_provider_id_weekday_opens_at_pk" PRIMARY KEY("provider_id","weekday","opens_at"),
	CONSTRAINT "provider_hours_weekday" CHECK ("provider_hours"."weekday" between 1 and 7),
	CONSTRAINT "provider_hours_order" CHECK ("provider_hours"."closes_at" > "provider_hours"."opens_at")
);
--> statement-breakpoint
CREATE TABLE "services" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"provider_id" uuid NOT NULL,
	"name" text NOT NULL,
	"description" text,
	"duration_minutes" integer NOT NULL,
	"price_cents" integer NOT NULL,
	"price_is_from" boolean DEFAULT false NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "services_duration_range" CHECK ("services"."duration_minutes" between 5 and 480),
	CONSTRAINT "services_price_nonnegative" CHECK ("services"."price_cents" >= 0)
);
--> statement-breakpoint
