-- Hand-written (drizzle cannot express EXCLUDE): a provider can never have two active bookings whose
-- times overlap, whichever services they are for — a groomer washing Freddy 10.00–11.00 cannot also
-- trim nails at 10.30. '[)' makes ranges half-open, so 10.00–11.00 and 11.00–12.00 may both exist.
-- Cancelled rows are ignored, so cancelling frees the time. Concurrent inserts are serialised by the
-- index: exactly one succeeds, the other fails with 23P01 (exclusion_violation) → HTTP 409.
-- The same GiST index serves the "which slots are taken" lookup for a provider and date range.
ALTER TABLE "bookings" ADD CONSTRAINT "bookings_no_overlap" EXCLUDE USING gist ("provider_id" WITH =, tstzrange("starts_at", "ends_at", '[)') WITH &&) WHERE ("status" <> 'cancelled');
